referenceAccess.arguments:
{"command": "$urls = [ordered]@{
 'hone/hone.py'          = 'https://raw.githubusercontent.com/chamkank/hone/master/hone/hone.py';
 'hone/utils/csv_utils.py'= 'https://raw.githubusercontent.com/chamkank/hone/master/hone/utils/csv_utils.py';
 'hone/utils/json_utils.py'='https://raw.githubusercontent.com/chamkank/hone/master/hone/utils/json_utils.py';
 'hone/utils/test_utils.py'='https://raw.githubusercontent.com/chamkank/hone/master/hone/utils/test_utils.py';
 'hone/__init__.py'      = 'https://raw.githubusercontent.com/chamkank/hone/master/hone/__init__.py';
 'hone/__main__.py'      = 'https://raw.githubusercontent.com/chamkank/hone/master/hone/__main__.py'
}
foreach ($k in $urls.Keys) {
  $c = (Invoke-WebRequest -Uri $urls[$k] -UseBasicParsing).Content
  $b = [System.Text.Encoding]::UTF8.GetBytes($c)
  $sha = [System.Security.Cryptography.SHA256]::Create().ComputeHash($b)
  '{0,-26} bytes={1,-6} endswithLF={2,-6} sha256b64={3}' -f $k, $b.Length, $c.EndsWith("`n"), [Convert]::ToBase64String($sha)
}", "description": "Fetch raw sources and compute byte sizes and SHA-256"}
